// Deriva el segmento del huésped combinando group_composition + travel_reason
// Reglas (en orden de prioridad):
//   1. group_composition === 'family'  → family  (trumps travel_reason)
//   2. travel_reason === 'business'    → business
//   3. travel_reason === 'honeymoon'   → honeymoon
//   4. travel_reason === 'adventure'   → adventure
//   5. cualquier otra combinación       → none (sin memory pack, perfil genérico)

const groupComposition = ($json.group_composition || '').trim().toLowerCase();
const travelReason = ($json.travel_reason || '').trim().toLowerCase();

let segment = 'none';

if (groupComposition === 'family') {
  segment = 'family';
} else if (travelReason === 'business') {
  segment = 'business';
} else if (travelReason === 'honeymoon') {
  segment = 'honeymoon';
} else if (travelReason === 'adventure') {
  segment = 'adventure';
}

return {
  segment,
  group_composition: groupComposition,
  travel_reason: travelReason,
  matched: segment !== 'none'
};

// Merge: datos del huésped (input 0) + memory pack (input 1, opcional) + webhook
const guest = $input.all()[0].json;
const memoryPackRow = $input.all()[1]?.json;
const hasMemoryPack = memoryPackRow && memoryPackRow.segment && memoryPackRow.segment !== 'none';
const stayWebhook = $('Recibir check-in').item.json;

const enrichedProfile = {
  guest_name: guest.name,
  language: guest.language || 'es',
  country: guest.country,
  email: guest.email,
  current_stay: {
    check_in_date: stayWebhook.check_in_date,
    room_number: stayWebhook.room_number,
    group_composition: stayWebhook.group_composition,
    travel_reason: stayWebhook.travel_reason
  },
  segment: hasMemoryPack ? memoryPackRow.segment : 'generic',
  baseline_recommendations: hasMemoryPack ? (memoryPackRow.baseline_recommendations || {}) : {},
  prompt_additions: hasMemoryPack ? (memoryPackRow.prompt_additions || '') : '',
  personalization_level: hasMemoryPack ? 'segment_baseline' : 'generic_only'
};

return enrichedProfile;
